{
  "items": [
    {
      "title": "European Values Study 2017: Integrated Dataset (EVS 2017)",
      "url_or_doi": "https://doi.org/10.4232/1.13897",
      "justification": "This cross-national survey conducted between 2017 and 2021 covers European and Eurasian countries (including Albania, Armenia, Austria, Azerbaijan, Belarus, Bosnia and Herzegovina, Bulgaria, Croatia, Czech Republic, Denmark, Estonia, Finland, France, Georgia, Germany, Great Britain, Hungary, Iceland, Italy, Lithuania, Montenegro, Netherlands, North Macedonia, Norway, Poland, Romania, Russian Federation, Serbia, Slovakia, Slovenia, Sweden, Spain, Switzerland, Portugal, Ukraine, and Latvia) and captures opinions and attitudes on family life, marriage, childbearing, and gender roles."
    },
    {
      "title": "Joint EVS/WVS 2017-2022 Dataset",
      "url_or_doi": "https://doi.org/10.4232/1.14320",
      "justification": "This harmonized dataset integrates data from the European Values Study 2017 and World Values Survey Wave 7 (2017–2022), providing comprehensive comparative data on family values, partnership perceptions, marriage, and household responsibilities across European nations during the late 2010s and early 2020s."
    },
    {
      "title": "Generations and Gender Programme Data Catalog",
      "url_or_doi": "https://www.ggp-i.org/data/",
      "justification": "The Generations and Gender Survey (GGS) rounds collected during the 2010s and 2020s (GGS-I and GGS-II) provide longitudinal micro-level demographic survey data on partnership dynamics, marriage, fertility intentions, and family life across European and Eurasian countries."
    },
    {
      "title": "Eurostat Crude Marriage Rate Dataset (tps00206)",
      "url_or_doi": "https://doi.org/10.2908/tps00206",
      "justification": "Provides official annual statistical indicators on marriage rates across European countries throughout the 2010s and 2020s, facilitating cross-national demographical analysis of marriage trends."
    }
  ]
}
```
